// Lee el total de la primera página (activas) y genera un item por cada página necesaria
const p1 = $input.first().json;
const total = p1.paging?.total ?? 0;
const token = $('Edit Fields').first().json['Access Token'];
const sellerId = $('Edit Fields').first().json.seller_id;
const limit = 50;
const status = 'active';

if (total === 0) return [];

const out = [];
for (let offset = 0; offset < total; offset += limit) {
  out.push({ json: { offset, limit, token, sellerId, status } });
}
return out;

// Lee el total de la primera página (pausadas) y genera un item por cada página necesaria
const p1 = $input.first().json;
const total = p1.paging?.total ?? 0;
const token = $('Edit Fields').first().json['Access Token'];
const sellerId = $('Edit Fields').first().json.seller_id;
const limit = 50;
const status = 'paused';

if (total === 0) return [];

const out = [];
for (let offset = 0; offset < total; offset += limit) {
  out.push({ json: { offset, limit, token, sellerId, status } });
}
return out;

// Junta los results de todas las páginas (activas + pausadas), deduplica IDs y arma batches de 20
const token = $('Edit Fields').first().json['Access Token'];
const allIds = [];
const seen = new Set();
for (const item of $input.all()) {
  const results = item.json.results || [];
  for (const id of results) {
    if (!seen.has(id)) {
      seen.add(id);
      allIds.push(id);
    }
  }
}
if (allIds.length === 0) return [];
const out = [];
for (let i = 0; i < allIds.length; i += 20) {
  out.push({ json: { ids_csv: allIds.slice(i, i + 20).join(','), token } });
}
return out;

// La respuesta de /items?ids=... puede llegar como array o como items separados.
// El status (active/paused) viene directo del detalle de ML: es el dato real y actual.
// shipping.logistic_type === 'fulfillment' indica que la publicacion opera con Full, pero
// OJO: si el item tiene inventory_id, available_quantity es la SUMA de Full + deposito propio
// (modelo de inventario combinado). El stock Full real hay que pedirlo aparte (siguiente nodo).
const results = [];
for (const item of $input.all()) {
  const data = item.json;
  const entries = Array.isArray(data) ? data : [data];
  for (const r of entries) {
    if (r && r.code === 200 && r.body) {
      const b = r.body;
      results.push({
        json: {
          item_id: b.id,
          title: b.title,
          price: b.price,
          currency_id: b.currency_id,
          available_quantity: b.available_quantity,
          sold_quantity: b.sold_quantity,
          condition: b.condition,
          status: b.status,
          listing_type_id: b.listing_type_id,
          logistic_type: b.shipping?.logistic_type ?? null,
          inventory_id: b.inventory_id ?? null,
          permalink: b.permalink
        }
      });
    }
  }
}
return results;

// Si el item tiene inventory_id (modelo de inventario combinado Full + deposito propio),
// available_quantity NO es el stock Full real: hay que consultarlo aparte por inventario.
// Este endpoint devuelve exclusivamente lo que hay fisicamente en los depositos Full de ML.
//
// Se consulta en LOTES EN PARALELO (no uno por uno) para no demorar ~300ms x cada item con
// inventario combinado, y se deduplica inventory_id por si varias publicaciones comparten
// el mismo inventario (evita pedir dos veces lo mismo).
const token = $('Edit Fields').first().json['Access Token'];
const items = $input.all().map(i => ({ ...i.json }));

const idsUnicos = [...new Set(items.filter(it => it.inventory_id).map(it => it.inventory_id))];
const CONCURRENCIA = 15;
const stockPorInventario = new Map();

for (let i = 0; i < idsUnicos.length; i += CONCURRENCIA) {
  const lote = idsUnicos.slice(i, i + CONCURRENCIA);
  const respuestas = await Promise.all(lote.map(async (invId) => {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.mercadolibre.com/inventories/${invId}/stock/fulfillment`,
        headers: { Authorization: `Bearer ${token}` },
        json: true,
      });
      return [invId, resp?.available_quantity ?? null];
    } catch (e) {
      return [invId, null];
    }
  }));
  for (const [invId, valor] of respuestas) stockPorInventario.set(invId, valor);
}

return items.map(it => ({
  json: {
    ...it,
    full_stock_real: it.inventory_id ? (stockPorInventario.get(it.inventory_id) ?? null) : null,
  }
}));
